import{_ as t,c as a,o,ah as s}from"./chunks/framework.D-P5O0CF.js";const u=JSON.parse('{"title":"Test data for local manual screenshots","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/qonnectra-demo-data/README.md","filePath":"scripts/qonnectra-demo-data/README.md"}'),i={name:"scripts/qonnectra-demo-data/README.md"};function n(r,e,d,c,p,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="test-data-for-local-manual-screenshots" tabindex="-1">Test data for local manual screenshots <a class="header-anchor" href="#test-data-for-local-manual-screenshots" aria-label="Permalink to &quot;Test data for local manual screenshots&quot;">​</a></h1><p><code>testprojekt-export.json</code> is a 1:1 export of the real project <strong>&quot;Testprojekt&quot;</strong> from app.geodock.de. <code>scripts/setup-local-qonnectra.sh</code> imports it into a fresh local instance automatically.</p><p>It covers everything the export account may read: nodes, trenches, conduits, microducts, addresses, residential units, cables, fibers, areas, the patch panel modelling of the nodes (container, slot configurations, node structures) and the <strong>fiber splices</strong> on top of it, the valuation cost rates, the pipeline record with its inquiry area, attachment metadata, plus the associated reference data (companies, conduit/cable/component types, flags).</p><p>The fiber splices matter beyond their own chapter: without them every fiber trace ends at the cable, so the fault simulation reports &quot;Keine betroffenen Adressen&quot; and the &quot;Faserverbindungen&quot; section of the post compaction PDF stays empty. The same holds for the valuation, which only shows a hint as long as no cost rate is configured.</p><p>Not included, because the export account gets HTTP 403 on those endpoints (see <code>EXPECTED_FORBIDDEN</code> in <code>fetch_geodock_export.py</code>):</p><table tabindex="0"><thead><tr><th>Resource</th><th>Consequence</th></tr></thead><tbody><tr><td><code>wms-sources</code></td><td><code>wms-layers</code> comes through, but without the URL of the WMS server the layers cannot be recreated - the map shows the base map only</td></tr><tr><td><code>node-slot-divider</code>, <code>node-slot-clip-number</code></td><td>visual subdivision inside a slot configuration is missing; the slots themselves are there</td></tr><tr><td><code>node-trench-selection</code></td><td>the branch canvas starts without a preselected trench</td></tr></tbody></table><p><code>trench-conduit-canvas</code> does come through and is empty in production - no manually arranged trench profile has been saved there.</p><p>Attachments are imported as <strong>metadata only</strong> (file name, type, path on api.geodock.de). The files themselves stay there: they are real documents of a real installation and have no place in this repository.</p><h2 id="updating-the-data" tabindex="-1">Updating the data <a class="header-anchor" href="#updating-the-data" aria-label="Permalink to &quot;Updating the data&quot;">​</a></h2><p><code>fetch_geodock_export.py</code> pulls the whole project through the API and writes the JSON file. Standard library only, no extra dependency.</p><ol><li><p>Put the credentials of the export account next to the script:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/qonnectra-demo-data/.env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/qonnectra-demo-data/.env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Fill in <code>GEODOCK_USERNAME</code> / <code>GEODOCK_PASSWORD</code>. <code>.env</code> is gitignored and must never be committed; the script never prints the values.</p></li><li><p>Fetch:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/qonnectra-demo-data/fetch_geodock_export.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/qonnectra-demo-data/testprojekt-export.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>It prints a row count per resource, so a resource that silently ran dry is visible. The four endpoints above are reported as &quot;not readable for this account&quot; - that is expected and not a failure. Everything else that fails makes the run exit non-zero.</p></li><li><p>Import it into the local instance (see below) and run the specs of the affected chapters - new data can invalidate images and the assertions that guard them.</p></li></ol><p><code>--host</code> and <code>--project</code> target a different installation, <code>--skip</code> leaves a resource out.</p><p>Two details of the export format worth knowing:</p><ul><li>GeoJSON resources (<code>trench</code>, <code>node</code>, <code>address</code>, <code>area</code>) are flattened to <code>{**properties, &quot;geometry&quot;: ...}</code>, which is the shape the importer reads.</li><li>Resources with no project filter of their own are fetched per parent object (<code>node-structure?node=&lt;uuid&gt;</code>, <code>fiber-splice?node_structure=&lt;uuid&gt;</code>, ...). Because not every serializer returns the relation it was queried by - a container exposes no <code>uuid_node</code> - each of those rows carries the query it came from in <code>_fetched_with</code>.</li></ul><h2 id="import-command" tabindex="-1">Import command <a class="header-anchor" href="#import-command" aria-label="Permalink to &quot;Import command&quot;">​</a></h2><p><code>import_geodock_export.py</code> is copied by <code>setup-local-qonnectra.sh</code> into <code>local-app/backend/apps/api/management/commands/</code> (local-app/ is gitignored and is refilled from the checkout on every run). After that:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import_geodock_export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/file.json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--force]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Without <code>--force</code> an already existing local project &quot;Testprojekt&quot; is skipped (no re-import). With <code>--force</code> it is deleted completely first and imported again.</p><p>Reference data (companies, conduit/cable types, flags, ...) is merged with the entries already present locally by matching names (<code>get_or_create</code>); objects with a UUID primary key are created with the ORIGINAL UUID from production, so that relations work without an additional id mapping.</p><p>The project itself is created with the fixed primary key <strong>2</strong> (<code>PROJECT_ID</code>). That is what a fresh instance produces anyway (&quot;Default&quot; takes 1), and it has to stay stable: the Playwright setup pins the cookie <code>selected-project=2</code> and the URLs of the app contain the id. Without pinning, a re-import with <code>--force</code> would hand out the next free id and every capture run would land in &quot;Default&quot;.</p>`,20)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
